def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    players = 1 + len(alive_opponents)
    affordable = max(0, int(supply) // WATER_REQ)
    shortage = max(0, players - affordable)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, 35)
        return min(budget, 18)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water >= 2:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 2)
    elif hp <= 4 or no_water >= 1:
        bid = max(0.72 * DAILY_SALARY, highest_prev + 1)
    else:
        if shortage <= 0:
            bid = 0.28 * DAILY_SALARY
        elif shortage == 1:
            bid = max(0.45 * DAILY_SALARY, avg_prev + 1)
        else:
            bid = max(0.62 * DAILY_SALARY, highest_prev + 1.5)

    if urgent_opponents >= max(1, len(alive_opponents) // 2):
        bid += 4
    if rich_opponents >= max(1, len(alive_opponents) // 2):
        bid += 3
    if int(supply) <= MIN_SUPPLY + 1:
        bid += 5
    elif int(supply) >= MAX_SUPPLY - 1 and hp > 4 and no_water == 0:
        bid -= 4

    reserve = 0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve = DAILY_SALARY * 0.15

    max_spend = max(0, budget - reserve)
    if hp <= 2 or no_water >= 2:
        max_spend = budget

    bid = min(bid, max_spend)
    bid = max(0, bid)

    if 0 < bid < 1:
        bid = 1

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents are alive, conserve budget.
    if not alive_opponents:
        cap = DAILY_SALARY * 0.4
        return min(budget, cap)

    # Read yesterday bids from previous_trace only (immediate reaction).
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive pressure.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Supply-aware baseline: when supply is tight, increase willingness to pay.
    # supply in [15,25]; map to a multiplier in [~1.2, ~0.8]
    if supply <= 0:
        tight_mult = 1.0
    else:
        tight_mult = 1.2 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
        if tight_mult < 0.8:
            tight_mult = 0.8
        if tight_mult > 1.2:
            tight_mult = 1.2

    # Our risk profile: low hp or many no-water days => bid harder.
    danger = 0
    if hp <= 2.0:
        danger = 2
    elif hp <= 3.0:
        danger = 1
    if no_water_days >= 2:
        danger += 1

    # If someone was bidding very high yesterday (near our salary), assume strong scarcity contest.
    strong_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    # Core bid target.
    if strong_pressure:
        if danger >= 2:
            target = DAILY_SALARY * 0.95 * tight_mult
        else:
            target = max(highest_prev_bid + 1.5, DAILY_SALARY * 0.3) * (1.0 if danger == 0 else 1.15)
    else:
        # Not extreme: try to outbid the second-highest slightly.
        # If highest was still meaningful, bid around it; else bid a moderate amount.
        anchor = max(second_prev_bid, highest_prev_bid * 0.9)
        base = max(DAILY_SALARY * 0.45, anchor + 1.0)
        target = base * tight_mult

    # Ensure we do not overpay beyond budget and keep some optionality.
    # Use a soft cap based on remaining budget.
    # If budget is low, bid proportionally.
    if budget <= 0:
        return 0.0

    # Hard cap: never exceed budget.
    bid = min(budget, target)

    # If budget is extremely low, still bid enough to avoid total collapse when danger is high.
    if bid < 1e-6 and danger >= 2:
        bid = min(budget, DAILY_SALARY * 0.5)

    # Final sanity: bid should be non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

